    "camera_detail.zones_description": "Draw areas on the live frame and give them jobs. Named areas let rules target places (person in Driveway) without hiding anything; loiter areas and tripwires power their matching rule types; masks hide pixels from the AI entirely; a veto area pauses all alerts while something is inside it.",
