    "camera.zones.kind_desc.include": "Mask: the AI sees ONLY these areas. Everything else is blacked out before detection, faces, and captions.",
    "camera.zones.kind_desc.exclude": "Mask: blacks the area out of everything the AI sees. For the neighbor's yard or a TV screen.",
    "camera.zones.kind_desc.veto": "While something is detected in here, ALL alerts on this camera pause. Kills headlight-flare false alarms on a wall.",
