    "camera_detail.zones": "Zonas y líneas de cruce",
    "camera_detail.zones_description": "Dibuja zonas en el fotograma en directo y asígnales funciones. Las zonas con nombre permiten que las reglas apunten a lugares (persona en Entrada) sin ocultar nada; las zonas de permanencia y las líneas de cruce activan sus reglas; las máscaras ocultan píxeles a la IA; una zona veto pausa todas las alertas mientras haya algo dentro.",
