    "camera.zones.kind.signal": "Semáforo",
    "camera.zones.kind_desc.zone": "Dibuja y nombra una zona (\"Entrada\"). Las reglas pueden apuntar a ella: persona en Entrada. La IA no oculta nada.",
    "camera.zones.kind_desc.loiter": "Zona preparada para alertas que registra cuánto tiempo permanece alguien dentro. Combínala con una regla de permanencia.",
