    "camera.zones.kind_desc.include": "Máscara: la IA solo ve estas zonas. Todo lo demás se oscurece antes de detectar, reconocer rostros o generar textos.",
    "camera.zones.kind_desc.exclude": "Máscara: oscurece la zona para todo lo que ve la IA. Útil para el jardín del vecino o una pantalla de televisión.",
    "camera.zones.kind_desc.veto": "Mientras se detecte algo aquí, todas las alertas de esta cámara se pausan. Evita falsas alarmas por reflejos de faros en una pared.",
    "camera.zones.kind_desc.signal": "Dibuja una caja sobre un semáforo. Nurby lee su color (rojo/ámbar/verde) para activar una regla de \"Cruce en rojo\" cuando el semáforo está realmente en rojo.",
    "camera.zones.mask_warning": "Aviso: tienes máscaras de \"Vigilar solo aquí\" e \"Ignorar\". Cuando existe una máscara de vigilancia, todo lo que queda fuera ya se ignora, así que las zonas de ignorar son redundantes. Conserva un solo estilo.",
